-- https://lua.expert

local v1, v2

return {
    Get = function() -- Get | line: 4
        -- upvalues: v1 (ref), v2 (ref)
        if v2 then
            return v2
        end

        v1 = game:GetService("AssetService"):CreateEditableImage({
            Size = Vector2.new(72, 60)
        })
        assert(v1, "Unable to allocate bike artwork")

        local v4 = buffer.create(17280)
        local t2 = {}

        for i = 1, 64 do
            t2[("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"):byte(i)] = i - 1
        end

        local t3 = {}

        for i = 1, 72, 8 do
            local v6 = tonumber(("00000000ffffff04ffffff6effffff52ffffffcffffffffdffffffb3ffffff2fffffff8d"):sub(i, i + 1), 16)
            local v8 = tonumber(("00000000ffffff04ffffff6effffff52ffffffcffffffffdffffffb3ffffff2fffffff8d"):sub(i + 2, i + 3), 16)
            local v10 = tonumber(("00000000ffffff04ffffff6effffff52ffffffcffffffffdffffffb3ffffff2fffffff8d"):sub(i + 4, i + 5), 16)
            local v12 = tonumber(("00000000ffffff04ffffff6effffff52ffffffcffffffffdffffffb3ffffff2fffffff8d"):sub(i + 6, i + 7), 16)

            table.insert(t3, v6 + v8 * 256 + v10 * 65536 + v12 * 16777216)
        end

        local n1 = 0

        for i = 1, 972, 3 do
            local v14 = t3[t2[(""):byte(i)] * 64 + t2[(""):byte(i + 1)] + 1]

            for _ = 1, t2[(""):byte(i + 2)] + 1 do
                buffer.writeu32(v4, n1, v14)
                n1 += 4
            end

            if i % 12288 == 1 then
                task.wait()
            end
        end

        assert(n1 == 17280, "Artwork pixel count mismatch")
        v1:WritePixelsBuffer(Vector2.zero, Vector2.new(72, 60), v4)
        v2 = Content.fromObject(v1)

        return v2
    end
}
